```javascript
import * as THREE from 'three/webgpu';
import { MeshPhysicalNodeMaterial, color } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'home-ornamental-divider';
  group.position.set(-2.5, 0.7, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  let mesh = null;
  let jewelMat = null;
  let ruleMat = null;

  const ink = new THREE.Color(config?.visual?.colors?.ink || '#16161d');
  const accent = new THREE.Color(config?.visual?.colors?.accent || '#ff2a38');

  const meshUrl = '/prism-mock/home/nodes/cta-hero.glb';

  const fallback = () => {
    const ruleGeo = new THREE.BoxGeometry(1.6, 0.02, 0.02);
    ruleMat = new MeshPhysicalNodeMaterial();
    ruleMat.colorNode = color(ink);
    ruleMat.metalness = 0.5;
    ruleMat.roughness = 0.55;
    ruleMat.clearcoat = 0.2;
    const rule = new THREE.Mesh(ruleGeo, ruleMat);

    const jewelGeo = new THREE.SphereGeometry(0.06, 24, 24);
    jewelMat = new MeshPhysicalNodeMaterial();
    jewelMat.colorNode = color(accent);
    jewelMat.metalness = 0.4;
    jewelMat.roughness = 0.3;
    jewelMat.clearcoat = 0.25;
    const jewel = new THREE.Mesh(jewelGeo, jewelMat);

    const holder = new THREE.Group();
    holder.add(rule, jewel);
    mesh = holder;
    group.add(holder);
  };

  try {
    const gltf = ctx.glbLoader.load(meshUrl);
    if (gltf && gltf.scene) {
      mesh = gltf.scene;
      group.add(mesh);
    } else {
      fallback();
    }
  } catch (e) {
    fallback();
  }

  (config?.cinematicPrimitives || []).forEach((primitive) => {
    if (ctx.primitives[primitive.name]) {
      ctx.primitives[primitive.name](group, primitive.params);
    }
  });

  let hoverTl = null;
  let pressTl = null;

  const baseY = group.position.y;

  const onHoverIn = () => {
    hoverTl && hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY + 0.15,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  const onHoverOut = () => {
    hoverTl && hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: baseY,
      duration: 0.7,
      ease: 'power3.out'
    });
  };

  const onClick = () => {
    pressTl && pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out'
    }).to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'back.out'
    });

    if (group.userData.emit) {
      group.userData.emit('hub-home.select', { itemId: group.name });
    }
  };

  group.userData.handlers = {
    hover: onHoverIn,
    hoverIn: onHoverIn,
    hoverOut: onHoverOut,
    click: onClick
  };

  group.userData.cleanup = () => {
    hoverTl && hoverTl.kill();
    pressTl && pressTl.kill();

    group.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        const mats = Array.isArray(obj.material) ? obj.material : [obj.material];
        mats.forEach((m) => {
          if (m.map) m.map.dispose();
          m.dispose();
        });
      }
    });

    if (ruleMat) ruleMat.dispose();
    if (jewelMat) jewelMat.dispose();
  };

  return group;
}
